import type { NoteHistoryEntryResponseDto } from "@repo/sdk";
import { noteControllerFindHistory } from "@repo/sdk";
import { useQuery } from "@tanstack/react-query";

/**
 * Fetches the full, automatic change history of a note (most recent first).
 * History entries are generated by the backend whenever the note is created
 * or one of its tracked fields (content, config, tags, coordinates, parent)
 * is updated — they cannot be created or edited directly by the client.
 */
export function useNoteHistoryQuery(
	projectId: number,
	noteId: number,
	options?: { enabled?: boolean },
) {
	return useQuery({
		queryKey: ["notes", projectId, noteId, "history"],
		queryFn: async () => {
			const response = await noteControllerFindHistory({
				path: { projectId, id: noteId },
			});
			return (response.data ?? []) as NoteHistoryEntryResponseDto[];
		},
		enabled:
			!Number.isNaN(projectId) &&
			!Number.isNaN(noteId) &&
			(options?.enabled ?? true),
	});
}
